   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Further on, this mapping needs to be implemented in the pre-VCD mapping tool as depicted in the use-case diagram in Figure 9, i.e. a list of criteria to be matched is submitted to the entity performing the mapping.",
     "role": "statement"
    }
   ]
  },
