   "id": "M1:T19",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Identity and access management MUST provide an interface to submit sensitive economic operator data (for example by uploading attestations that verify sensitive economic operator data) in order to allow the economic operator to apply for the creation of a VCD account.",
     "role": "statement"
    },
    {
